Now add the dependency. Let me create the auth package first, then go get / go mod tidy.

Create /work/auth/auth.go:

```go
package auth

import (
	"errors"

	"golang.org/x/crypto/bcrypt"
)

var ErrInvalidHash = errors.New("auth: invalid password hash")

func HashPassword(password string) (string, error) {
	hash, err := bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost)
	if err != nil {
		return "", err
	}
	return string(hash), nil
}

func CheckPassword(hash, password string) error {
	return bcrypt.CompareHashAndPassword([]byte(hash), []byte(password))
}
```

And test:

```go
package auth

import "testing"

func TestHashPasswordAndCheckPassword(t *testing.T) {
	hash, err := HashPassword("correct horse battery staple")
	if err != nil {
		t.Fatalf("HashPassword: %v", err)
	}
	if hash == "correct horse battery staple" {
		t.Fatal("password was not hashed")
	}
	if err := CheckPassword(hash, "correct horse battery staple"); err != nil {
		t.Fatalf("CheckPassword with correct password: %v", err)
	}
	if err := CheckPassword(hash, "wrong"); err == nil {
		t.Fatal("CheckPassword with wrong password: expected error")
	}
}
```

And main.go:

```go
package main

import (
	"fmt"
	"log"

	"example.com/secureapp/auth"
)

func main() {
	hash, err := auth.HashPassword("s3cret")
	if err != nil {
		log.Fatal(err)
	}
	fmt.Println(hash)
	if err := auth.CheckPassword(hash, "s3cret"); err != nil {
		log.Fatal(err)
	}
	fmt.Println("password verified")
}
```

Then go mod tidy will add golang.org/x/crypto and go.sum. Need network for module download. GOPROXY default is proxy.golang.org. Let's try.

